&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Design and analyze &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;vehicle &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;structures, mechanisms, and actuated systems&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; with a focus on &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;dynamics, kinematics, and structural integrity&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Develop, optimize, and maintain &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;CAD models&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; for mechanical components and assemblies.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Conduct &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;multibody dynamics simulations&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; to assess system performance under real-world conditions.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
