&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Investigate and resolve &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;mechanical failures to improve system reliability.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259,&amp;quot;335559991&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Support &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;prototype development, testing, and validation&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; of vehicle components as part of a multi-disciplinary team.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What Success Looks Like:&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
